def solve(pairs):
    if not pairs:
        return pairs
    result = {}
    seen_names = []
    for name, score in pairs:
        if name not in result:
            seen_names.append(name)
        result[name] = max(result.get(name, -float('inf')), score)
    return {name: result[name] for name in seen_names}
